def hermes_bin() -> str:
    # Services often run without ~/.local/bin on PATH; that link is the live install's own launcher,
    # so check it before the old default folder (7 Oct 2026: the old folder held stale code).
    cands = [os.environ.get("HERMES_BIN"), shutil.which("hermes"), str(Path.home() / ".local" / "bin" / "hermes"),
             str(HERMES_HOME / "hermes-agent" / "hermes")]
    for c in cands:
        if c and Path(c).exists():
            return c
    raise Fail("cannot find the hermes command. State: nothing changed. Fix: set HERMES_BIN=/path/to/hermes "
               "or put hermes on PATH, then retry.")

def send_notices(work: dict, req: dict, gs, key, log, dry: bool) -> None:
    text = notice_text(req)
    base = api_base(gs)
    if not dry:
        atomic_write(NOTICE_FILE, json.dumps({"phase": "coming", "request": req["id"], "text": text,
                                              "deadline_at": req["deadline_at"]}))
    for profile, items in sorted(work["by_profile"].items()):
        for it in items:
            if it["kind"] == "kanban worker":
                res = "would comment on the card" if dry else kanban_comment(it["task_id"], text)
                log("notice", f"{profile}: {it['detail']} -> {res}. (A card only sees the comment when it next reads the "
                              f"card; the gateway restart may still cut it, and the dispatcher re-runs it.)")
            elif it.get("run_id"):
                res = "would steer" if dry else steer(base, key, it["run_id"], text)
                log("notice", f"{profile}: {it['session']} -> {res}", loud=res.startswith("steer failed"))
            else:
                log("notice", f"{profile}: {it['kind']} ({it['detail']}) CANNOT be reached mid-turn - Hermes lists no run id "
                              f"for it, and Bot Chat/queued messages only arrive after the turn ends (and new turns are "
                              f"refused while draining). It will see the notice only if it reads {NOTICE_FILE}. "
                              f"It keeps running until it finishes or the deadline.", loud=True)
    if work["unnamed"]:
        log("notice", f"{work['unnamed']} unnamed API-run/deferred unit(s) cannot be addressed at all.", loud=True)

def wake_bots(profiles: list[str], req: dict, wake_cmd: str | None, log, dry: bool) -> dict:
    """Run the wake command once per bot, at most WAKE_TIMEOUT_SECONDS each. A failure is logged loudly and the
    next bot still gets its call. Returns {profile: "woken" | "failed" | "timeout"} (dry run: "would wake")."""
    text = back_online_text(req)
    results: dict[str, str] = {}
    if (wake_cmd or "").strip().lower() in WAKE_OFF:
        log("wake", "wake-up is off (--wake-cmd none): no Bot Chat message sent. Cut bots read the card comment or "
                    "restart-notice.json, or wait for Hermes to resume them.", loud=bool(profiles))
        return results
    if not profiles:
        log("wake", "would wake nobody: no bot is working now" if dry else "nobody to wake")
        return results
    for p in profiles:
        try:
            argv = wake_argv(wake_cmd, p, text)
        except (Fail, ValueError) as e:
            results[p] = "failed"
            log("wake", f"{p}: cannot build the wake command ({e}). Fix: pass --wake-cmd \"...\" or set HERMES_BIN.", loud=True)
            continue
        if dry:
            results[p] = "would wake"
            log("wake", f"would wake {p}: {shlex.join(argv)}")
            continue
        try:
            r = subprocess.run(argv, capture_output=True, text=True, timeout=WAKE_TIMEOUT_SECONDS,
                               stdin=subprocess.DEVNULL)
            if r.returncode != 0 and not wake_cmd and WAKE_BUSY_MARK in ((r.stdout or "") + (r.stderr or "")):
                # The bot's "Bot Chat" session is open in a live window (found on TurnerBook, tb-king, 7 Oct):
                # Hermes refuses a second writer. Send the text to a separate session so the bot still wakes.
                alt = [WAKE_ALT_SESSION if a == "Bot Chat" else a for a in argv]
                log("wake", f"{p}: Bot Chat is open in another window; sending the wake-up to session \"{WAKE_ALT_SESSION}\" instead")
                r = subprocess.run(alt, capture_output=True, text=True, timeout=WAKE_TIMEOUT_SECONDS,
                                   stdin=subprocess.DEVNULL)
            if r.returncode == 0:
                results[p] = "woken"
                log("wake", f"{p}: woken via Bot Chat (exit 0)")

def refuse_if_underway(r: dict, args) -> None:
    if r.get("cancel_requested"):
        # A joiner now would be told "joined" and then lose its reason when the coordinator cancels.
        raise Fail(f"request {r['id']} is being cancelled, so it cannot take your reason. State: nothing changed. "
                   f"Fix: run `request` again in a few seconds (the coordinator stops at its next poll, <= {POLL_SECONDS}s).")
    if r["status"] in ("restarting", "verifying"):
        raise Fail(f"restart {r['id']} is already underway ({r['status']}), so a change merged just now may NOT be in "
                   f"it. State: nothing changed. Fix: when it finishes (`{SCRIPT.name} status`), run `request` again; "
                   f"it will be scheduled after the {args.min_gap_minutes}-minute minimum gap as one restart.")

def coordinate(req: dict, args, log, dry: bool) -> None:
    if req.get("retain_pause") and not dry:
        return coordinate_retained(req, log)
    pause = DispatchPause(req["id"], log)
    try:
        _coordinate(req, args, log, dry, pause)
    finally:
        if not dry:
            pause.release()

def refuse_while_sessions_live(verb: str, args, *, host_home: Optional[Path] = None, profile: Optional[str] = None) -> None:
    """Exit 1 naming the live work unless ``--interrupt`` was passed; with it, say what is interrupted.
    ``host_home``/``profile``: a served profile's stop/restart unserves only that profile in the host,
    so only its work counts."""
    if profile:
        hint = f"hermes -p {profile} gateway {{verb}} {INTERRUPT_FLAG}"
        # No answer (control socket down) proceeds: the park marker path exists for exactly that host.
        lines = refusal_lines(verb, [Path(host_home)], profile=profile, flag_hint=hint)
    else:
        lines = refusal_lines(verb, _candidate_homes(getattr(args, "system", False)))
    if not lines:
        return
    from hermes_cli.gateway import print_error, print_warning

    if getattr(args, "interrupt", False):
        print_warning(lines[0].replace(f"Refusing to {verb} the gateway", f"--yes: {verb} proceeds"))
        for line in lines[1:-2]:
            print(line)
        return
    if sys.stdin.isatty() and sys.stdout.isatty():
        from hermes_cli.cli_output import prompt_yes_no

        print_warning(lines[0].replace(f"Refusing to {verb} the gateway", f"{verb.capitalize()} the gateway"))
        for line in lines[1:-2]:
            print(line)
        if prompt_yes_no(f"Interrupt them and {verb} the gateway?", default=False):
            return
        print(f"  Cancelled: the gateway was not {'stopped' if verb == 'stop' else 'restarted'}.")
        sys.exit(1)
    print_error(lines[0])
    for line in lines[1:]:
        print(line)
    sys.exit(1)
